import numpy as np, json
from collections import Counter
def f(I):
    I=np.array(I); H,W=I.shape
    cnt=Counter(I.flatten().tolist())
    bg=cnt.most_common(1)[0][0]
    comps=[]; seen=np.zeros_like(I,bool)
    for i in range(H):
        for j in range(W):
            if I[i,j]!=bg and not seen[i,j]:
                st=[(i,j)]; seen[i,j]=True; comp=[]
                while st:
                    y,x=st.pop(); comp.append((y,x))
                    for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<H and 0<=nx<W and I[ny,nx]==I[i,j] and not seen[ny,nx]:
                            seen[ny,nx]=True; st.append((ny,nx))
                ys=[p[0] for p in comp]; xs=[p[1] for p in comp]
                comps.append({'c':int(I[i,j]),'rows':(min(ys),max(ys)), 'cols':(min(xs),max(xs)), 'n':len(comp)})
    singles=[c for c in comps if c['n']==1]
    out=I.copy()
    for c in comps:
        if c['n']>1:
            # singleton whose col is inside block's col span
            best=None
            for s in singles:
                si,sj=s['cols']
                if si<=c['cols'][0] and sj>=c['cols'][1]:
                    cand=(abs(si-(c['rows'][0]+c['rows'][1])/2)+abs(sj-(c['cols'][0]+c['cols'][1])/2), int(I[si,sj]))
                    if best is None or cand<best: best=cand
            if best:
                for y in range(c['rows'][0],c['rows'][1]+1):
                    for x in range(c['cols'][0],c['cols'][1]+1):
                        out[y,x]=best[1]
    return out.tolist()
